{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    pts={i: next((v for v in row if v), None) for i,row in enumerate(grid)}
    marks=[(i,v) for i,v in pts.items() if v is not None]
    marks.sort()
    # horizontal boundaries: top, each marked row, bottom
    lines=[(0,marks[0][1])]+marks+[(h-1,marks[-1][1])]
    out=[[0]*w for _ in range(h)]
    for k,(r,c) in enumerate(lines):
        for x in range(w): out[r][x]=c
        if k+1<len(lines):
            nr,nc=lines[k+1]
            for y in range(r+1,nr):
                col=nc if y==nr-1 else c
                out[y][0]=out[y][-1]=col
    return out"}

